  status=Ui.text(this,"",13,Ui.CYAN);status.setContentDescription("Estado da Onda IA");body.addView(status);conversation=Ui.text(this,"Faça uma pergunta ou peça uma mensagem para um cartão.",15,Ui.TEXT);conversation.setTextIsSelectable(true);conversation.setContentDescription("Conversa com a Onda IA");body.addView(conversation,new LinearLayout.LayoutParams(-1,-2));preview=new ImageView(this);preview.setContentDescription("Cartão criado com mensagem da IA");preview.setAdjustViewBounds(true);preview.setMaxHeight(Ui.dp(this,360));preview.setVisibility(View.GONE);body.addView(preview,new LinearLayout.LayoutParams(-1,-2));
  input=new EditText(this);Ui.input(input);input.setSingleLine(false);input.setMinLines(2);input.setMaxLines(4);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(600)});input.setHint("Pergunte ou descreva o tema da mensagem");input.setContentDescription("Pedido para a Onda IA");body.addView(input,new LinearLayout.LayoutParams(-1,-2));LinearLayout actions=new LinearLayout(this);send=Ui.button(this,"Enviar",v->generate(false));send.setContentDescription("Enviar pergunta à IA local");Ui.primary(send);actions.addView(send,new LinearLayout.LayoutParams(0,-2,1));Button tasks=Ui.button(this,"Tarefas",v->startActivity(new Intent(this,AutomationActivity.class).putExtra("automation_draft",input.getText().toString())));tasks.setContentDescription("Revisar tarefa do Onda");actions.addView(tasks,new LinearLayout.LayoutParams(0,-2,1));body.addView(actions);
  Ui.Section creations=new Ui.Section(this,"Cartões e clipes",false);creations.content.addView(Ui.text(this,"Crie a mensagem com IA ou use seu próprio texto. Use fotos do celular ou os estilos do Onda. Clipes sem som.",12,Ui.MUTED));card=Ui.button(this,"Criar cartão",v->generate(true));card.setContentDescription("Criar cartão com mensagem da IA");creations.content.addView(card);creations.content.addView(Ui.button(this,"Cartão com meu texto",v->manualCard()));clip=Ui.button(this,"Animar cartão em MP4",v->animate());clip.setContentDescription("Criar clipe animado do cartão");creations.content.addView(clip);creations.content.addView(Ui.button(this,"Ver clipe criado",v->{if(lastFile==null||!"video/mp4".equals(lastMime)){Toast.makeText(this,"Crie um clipe primeiro",Toast.LENGTH_SHORT).show();return;}Uri uri=androidx.core.content.FileProvider.getUriForFile(this,getPackageName()+".share",lastFile);startActivity(new Intent(Intent.ACTION_VIEW).setClass(this,VideoActivity.class).setDataAndType(uri,"video/mp4").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}));save=Ui.button(this,"Salvar criação",v->save());creations.content.addView(save);share=Ui.button(this,"Compartilhar criação",v->{if(lastFile!=null)startActivity(Intent.createChooser(ImageSharing.send(this,lastFile,lastMime,"Criado no Onda"),"Compartilhar criação"));});creations.content.addView(share);body.addView(creations);
  body.addView(Ui.button(this,"Compartilhar resposta",v->{String value=history.isEmpty()?"":history.get(history.size()-1).answer;if(value.isEmpty()){Toast.makeText(this,"Envie uma pergunta primeiro",Toast.LENGTH_SHORT).show();return;}startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,value),"Compartilhar resposta"));}));body.addView(Ui.button(this,"Nova conversa",v->{if(busy)return;history.clear();conversation.setText("Nova conversa. Envie seu pedido.");}));stop=Ui.button(this,"Interromper",v->cancel());stop.setContentDescription("Interromper processamento da Onda IA");body.addView(stop);
  models.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int i,long id){getSharedPreferences("local_ai",0).edit().putInt("model",i).apply();update();}});if(state!=null){input.setText(state.getString("draft",""));ArrayList<String> turns=state.getStringArrayList("turns");if(turns!=null)for(int i=0;i+1<turns.size()&&history.size()<4;i+=2)history.add(new LocalAiPrompt.Turn(turns.get(i),turns.get(i+1)));if(!history.isEmpty())conversation.setText(transcript(null,null));lastCard=restore(state.getString("card"));lastFile=restore(state.getString("file"));pendingSave=restore(state.getString("save_file"));if(lastFile!=null)lastMime=lastFile.getName().endsWith(".mp4")?"video/mp4":"image/png";if(pendingSave!=null)pendingMime=pendingSave.getName().endsWith(".mp4")?"video/mp4":"image/png";if(lastCard!=null)showImage(lastCard);String photoFile=state.getString("photos");photos.addAll(LocalAiPhotos.restore(this,photoFile));if(!photos.isEmpty()){photoRequest=new File(getCacheDir(),photoFile);photoCount.setText(photos.size()+" fotos selecionadas");}}root.setFocusableInTouchMode(true);root.requestFocus();getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);update();
